(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mt"] = {"ui":{"skip":"Aqbeż għall-kontenut","back":"← Lura għal AI-gile","lang.button":"Lingwa: {name}","lang.dialog":"Agħżel lingwa","lang.search":"Fittex lingwa","lang.none":"Ebda lingwa ma taqbel","lang.notYet":"Għad m'hemmx traduzzjoni għal {name}","theme.aria":"Aqleb bejn it-tema ċara u dik skura","theme.toLight":"Aqleb għat-tema ċara","theme.toDark":"Aqleb għat-tema skura","index.title":"AI-gile: it-tim tal-iżvilupp tiegħek tal-AI, fuq bord wieħed","index.description":"AI-gile huwa bord kanban għal timijiet tal-kodiċi bl-AI. Jaħdmu waqt li torqod; inti tirċievi munzell wieħed qasir ta' affarijiet biex tiddeċiedi, tittestja u taċċetta.","hero.logoAlt":"Ikona tal-bord ta' AI-gile","hero.h1.html":"It-tim tal-iżvilupp tiegħek tal-AI, fuq bord&nbsp;wieħed.","hero.alpha":"🐣 Pre-alpha magħluqa","hero.alphaTitle":"Bikri u mhux lest: grazzi li qed tipprova!","hero.lede":"Jibnu waqt li torqod. Tqum għal munzell wieħed qasir: ftit mistoqsijiet, ftit affarijiet biex tittestja, djamant vjola jew tnejn. Ikklikkja, aċċetta, u lura għall-kafè tiegħek.","dl.windows":"Applikazzjoni għal Windows","dl.browser":"Mexxiha fil-browser tiegħek","dl.soon":"Dalwaqt","dl.notify":"🔔 Għarrafni meta tiftaħ","dl.notifySmall":"Alpha jew beta","hero.secondary":"Agile, imma t-tim qatt ma jeħtieġ kafè għall-istand-up. (Jagħmlu l-istand-ups xorta waħda.)","pitch.h2":"AI-gile fi kliem kemm trid","pitch.lede":"Agħżel tul, minn kelma waħda sa 144. Kull tul huwa deskrizzjoni waħedha, miktuba għal dak id-daqs. Iġbed is-slider jew uża t-tasti tal-vleġeġ.","pitch.rangeLabel":"Tul f'kliem","pitch.dice":"🎲 verżjoni oħra","pitch.words.one":"{n} kelma","pitch.words.few":"{n} kelmiet","pitch.words.many":"{n} kelma","pitch.words.other":"{n} kelma","pitch.letters.one":"{n} ittra","pitch.letters.few":"{n} ittri","pitch.letters.many":"{n} ittra","pitch.letters.other":"{n} ittra","pitch.chars.one":"{n} karattru","pitch.chars.few":"{n} karattri","pitch.chars.many":"{n} karattru","pitch.chars.other":"{n} karattru","count.line.html.one":"{n} karta fuq il-bord bħalissa","count.line.html.few":"{n} karti fuq il-bord bħalissa","count.line.html.many":"{n} karta fuq il-bord bħalissa","count.line.html.other":"{n} karta fuq il-bord bħalissa","features.aria":"X'jagħmel","f.pile.h":"Munzell wieħed għalik","f.pile.html":"<b>Għalik</b> iżomm kollox li qed jistenniek, fil-proġetti kollha: mistoqsijiet, affarijiet biex tittestja, kompiti li bniedem biss jista' jagħmel. Il-kju tiegħek jgħid x'inhu li jmiss u kemm se jieħu.","f.sleep.h":"Timijiet li jaħdmu waqt li torqod","f.sleep.p":"Kull proġett għandu lead u tim ta' aġenti tal-AI. Ikkumenta fuq karta u t-tim iqum, jagħmel ix-xogħol, u jirritornaha lura b'passi li bniedem għajjien jista' jsegwi.","f.tester.h":"Tester tal-AI jiċċekkja l-ewwel","f.tester.p":"Qabel ma xi ħaġa tasal għandek, tester isegwi l-passi f'kopja tal-app u juri x'ra, b'screenshot. Għaddi minn dawk li għaddew u aċċetta b'klikk wieħed.","f.proof.h":"Provi, mhux wegħdiet","f.proof.p":"Kull konsenja turi x'inbidel: il-fajls, id-diff, l-iscreenshots. M'għandekx bżonn tiftaħ kull app biex tara jekk huwiex lest.","f.chat.h":"Iddiskuti mal-leads tiegħek","f.chat.p":"Strixxa bi stil ta' Discord: ikona waħda għal kull proġett, djamanti vjola għal dak li jeħtieġek. Ibgħat idea lil lead; jagħmilha karti u pjan, b'buttuna ✅ Go.","f.tidy.h":"Iżomm lilu nnifsu f'ordni","f.tidy.p":"Karti relatati jingħaqdu f'waħda, titli mħawdin jissewwew, u kontroll tat-tokens iżomm il-kodiċi irqiq. Inqas affarijiet biex taqleb bejniethom, inqas biex taħseb fihom.","f.private.h":"Tiegħek, fuq il-kompjuter tiegħek","f.private.li1":"Il-bord jaħdem fuq il-magna tiegħek stess u jwieġeb lilek biss.","f.private.li2":"Il-messaġġi privati bejn in-nies huma ċifrati end-to-end.","f.private.li3":"L-ebda kont, l-ebda trackers, l-ebda cookies.","f.lang.h":"Bil-lingwa tiegħek","f.lang.p":"Aktar minn 120 lingwa, mill-Malti, il-Welsh u l-Ġappuniż sal-pirata, Yoda u l-Klingon, b'qlib mgħaġġel lura għall-Ingliż għall-kliem tal-iżviluppaturi.","tl.aria":"Skeda taż-żmien mill-ewwel konversazzjoni sal-pjan","tl.h2":"Mill-ewwel chat sa dak li jmiss","tl.lede":"Dati u ħinijiet reali, fiż-żona tal-ħin tiegħek. Wara llum huwa l-pjan, mingħajr dati mwiegħda.","tl.today":"Illum","tl.planned":"ippjanat","tl.cards.one":"{n} karta","tl.cards.few":"{n} karti","tl.cards.many":"{n} karta","tl.cards.other":"{n} karta","join.h2":"Ingħaqad magħna","join.lede":"AI-gile qed jinbena minn bniedem żgħir u numru kbir ta' aġenti paċenzjużi. Għalissa huwa privat, alpha magħluqa ma' ħbieb. Trid tipprova meta jinfetaħ?","join.btn":"Irreġistra l-interess","join.small":"Se nibagħtulek email, xejn aktar","footer.tag":"AI-gile. L-ebda trackers, l-ebda cookies, l-ebda kafè għall-istand-up.","footer.licence":"Liċenzja tan-negozju","footer.status":"Status","form.sending":"Qed jintbagħat…","form.failed":"Dak ma ħadimx: erġa' pprova aktar tard.","form.offline":"Ma setgħetx tintlaħaq AI-gile: erġa' pprova aktar tard.","interest.title":"AI-gile: għarrafni meta tiftaħ l-alpha","interest.description":"Ħalli l-email tiegħek biex tisma' meta tinfetaħ l-alpha jew il-beta magħluqa ta' AI-gile.","interest.h1":"🔔 Għarrafni meta tiftaħ","interest.lede":"AI-gile qiegħed f'pre-alpha magħluqa. Ħalli l-email tiegħek u niktbulek darba, meta jkun hemm post għalik.","interest.email":"L-email tiegħek","interest.which":"Liema test?","interest.alpha":"Alpha magħluqa: bikrija, mhux rfinuta, ħafna bidliet","interest.beta":"Beta: aktar stabbli, aktar tard","interest.both":"Kwalunkwe, dik li tiġi l-ewwel","interest.submit":"Poġġini fuq il-lista","interest.thanks":"Grazzi! Int fuq il-lista.","interest.kept":"Jinżammu biss l-email tiegħek u t-test li għażilt, għal din il-lista biss. L-ebda newsletter, l-ebda trackers.","licence.title":"AI-gile: liċenzja tan-negozju","licence.description":"Qed tuża AI-gile fin-negozju tiegħek? Applika għal liċenzja tan-negozju b'xejn.","licence.h1":"📜 Liċenzja tan-negozju","licence.lede":"Qed tuża AI-gile x-xogħol? Għidilna min int u x'tagħmel. Jekk jagħmel xi ġid, il-liċenzja hija b'xejn.","licence.company":"Kumpanija","licence.website":"Websajt","licence.what":"X'tagħmel","licence.how":"Kif jgħin id-dinja","licence.email":"Email","licence.submit":"Applika","licence.thanks":"Grazzi! Nirrispondulek bl-email.","status.title":"Status ta' AI-gile","status.h1":"Status ta' AI-gile","status.quiet":"Kollox kwiet","status.checking":"Qed jiċċekkja…","status.offline":"Is-servizz tal-istatus ma jistax jintlaħaq bħalissa (qed nerġgħu nippruvaw)","status.updated":"aġġornat {ago}","status.justNow":"għadu kif","status.min":"{n} min ilu","status.hours":"{n} sieg ilu","status.days":"{n} j ilu","live.h2":"Ara kif qed jinbena, live","live.caption":"Kull karta hija moħbija: tara l-forma tax-xogħol, mhux il-kliem.","live.watching.one":"live: {n} qed josservaw","live.watching.other":"live: {n} qed josservaw","live.offline":"Il-bord live qed jieħu nifs. Erġa' ejja dalwaqt.","live.cols":"Backlog|Biex isir|Għaddej|It-tim qed jivverifika|Għalik biex tittestja|Għat-tim|Lest","live.last.now":"L-aħħar karta tmexxiet ftit ilu","live.last.min.one":"L-aħħar karta tmexxiet {n} minuta ilu","live.last.min.other":"L-aħħar karta tmexxiet {n} minuti ilu","live.last.hour.one":"L-aħħar karta tmexxiet {n} siegħa ilu","live.last.hour.other":"L-aħħar karta tmexxiet {n} sigħat ilu","live.last.day.one":"L-aħħar karta tmexxiet {n} jum ilu","live.last.day.other":"L-aħħar karta tmexxiet {n} jiem ilu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Iddelegat."]},{"n":2,"texts":["Robots jaħdmu.","Aġenti, f'ordni.","Ideat, mibnija."]},{"n":3,"texts":["Kanban għar-robots.","Ideat isiru funzjonijiet.","B'xejn, lokali, ittestjat."]},{"n":5,"texts":["Bord kanban fejn jibnu l-aġenti.","Inti tikteb karti. Aġenti jibnu.","B'xejn, lokali, ittestjat, ftit iblah."]},{"n":8,"texts":["Bord kanban b'xejn fejn jaħdmu l-aġenti tal-AI.","Ikteb idea waħda. L-aġenti jibnuha. Inti taċċettaha.","Agile għal bniedem wieħed u ħafna robots paċenzjużi."]},{"n":13,"texts":["Bord kanban fuq il-kompjuter tiegħek fejn l-aġenti tal-AI jieħdu l-karti.","Ikteb idea. Tim sħiħ ta' aġenti jibnuha. Wara tester jiċċekkjaha sew għalik.","B'xejn, mingħajr kontijiet jew trackers: bord, ftit robots, u inti fil-kontroll."]},{"n":21,"texts":["AI-gile huwa bord kanban biex taħdem ma' aġenti tal-kodiċi bl-AI. Huma jieħdu l-karti kollha; inti tittestjahom u taċċettahom.","Kull proġett għandu lead u tim ta' aġenti tal-AI. Ikkumenta fuq kwalunkwe karta u t-tim jibda jaħdem.","Bord personali tal-affarijiet li jridu jsiru, b'xejn, li jaħdem fuq il-kompjuter tiegħek. Dawk li jaħdmu huma robots. Dak li jgħid iva int."]},{"n":34,"texts":["Inti tpoġġi l-ideat tiegħek fuq bord. Tim ta' aġenti tal-AI jibdilhom f'funzjonijiet li jaħdmu, jittestjahom, u jirritornawhom b'passi biex tipprova. Xejn ma jgħodd bħala lest sakemm int ma tgħidx hekk.","AI-gile huwa bord kanban magħmul id-dar li Rich bena b'ħafna għajnuna mill-aġenti li issa jmexxi. Huwa b'xejn, jaħdem fuq il-kompjuter tiegħek, u jinqasam ma' ħbieb, mhux jinbigħ.","Immaġina bord kanban tas-soltu, b'kolonni minn Backlog sa Lest, ħlief li l-karti jittieħdu mill-aġenti tal-AI. Jirrappurtaw il-progress, jistaqsu meta jibqgħu mwaħħla, u dejjem jistennew l-approvazzjoni tiegħek qabel ma jmorru 'l quddiem."]},{"n":55,"texts":["AI-gile huwa bord kanban fejn it-tim huwa magħmul minn aġenti tal-AI. Kull proġett għandu lead li jippjana x-xogħol u ħaddiema li jibnuh. Meta funzjoni tkun lesta, tester tal-AI jipprovaha u jieħu screenshot, imbagħad tasal fuq il-munzell tiegħek. Aċċettaha, jew ikkumenta u jerġgħu jaħdmu fuqha.","Beda bħala mod ta' persuna waħda biex iżomm rendikont ta' ħafna sessjonijiet tal-kodiċi bl-AI f'daqqa, u kiber f'bord veru. Jaħdem fuq il-magna tiegħek, ma jeħtieġ l-ebda kont u m'għandu l-ebda trackers. Huwa b'xejn għall-ħbieb u għal min hu kurjuż. Għadu wkoll mhux lest, għalhekk stenna xi truf mhux irfinati u sorpriża minn żmien għal żmien.","Din hija l-verżjoni onesta tal-istorja kollha. Xorta trid ikollok l-ideat, u xorta trid tiċċekkja r-riżultati. Dak li jagħmel AI-gile huwa dak kollu li hemm bejniethom: iżomm il-karti f'ordni, iqajjem l-aġent t-tajjeb meta tikkumenta, juri eżattament x'inbidel, u jżomm kollox f'munzell qasir wieħed biss għalik, mingħajr storbju."]},{"n":89,"texts":["AI-gile huwa bord kanban kompletament b'xejn li tmexxi fuq il-kompjuter tiegħek stess. Minflok in-nies, kull proġett għandu tim sħiħ ta' aġenti tal-AI: lead li jibdel l-ideat tiegħek f'karti u pjan, u għajnuna li tieħu l-karti skont il-prijorità. Meta xi ħaġa tinbena, tester tal-AI isegwi l-passi tat-test u juri lilek x'ra, b'screenshot. Imbagħad tistenna f'munzell wieħed biss jismu Għalik. Inti taċċettaha, jew tikkumenta u t-tim jerġa' jipprova mill-ġdid. Xejn ma jasal qatt f'Lest mingħajrek.","Ftit karatteristiċi li forsi ma tistennihomx. Għassa tal-lejl iżżomm il-kolonna Biex isir mimlija waqt li torqod, billi tagħżel karti li ma jeħtieġux tweġiba minnek. Għadd tat-tokens juri kemm użaw l-aġenti llum u din il-ġimgħa, u l-Mod bla Tokens jgħidilhom jieqfu jonfqu. Tista' tibgħat messaġġi lill-ħbieb, u l-messaġġi privati huma ċifrati end-to-end. Il-bord jitkellem madwar 120 lingwa, fosthom il-Malti, il-pirata u l-Klingon. Xejn minn dan ma jiswa xejn, u ħadd ma qed jipprova jbigħhulek.","AI-gile huwa proġett żgħir u personali, mhux kumpanija. Rich xtaq jieħu ħsieb diversi proġetti tal-kodiċi bl-AI mingħajr ma jiftaħ kull app biex jiċċekkjahom, allura hu u l-aġenti bnew bord għal dan, u mbagħad użaw il-bord biex jibnu l-bqija tiegħu nnifsu. Qiegħed f'pre-alpha magħluqa, li jfisser li jaħdem, il-biċċa l-kbira, għal ftit ħbieb. M'hemm l-ebda paġna tal-prezzijiet, l-ebda newsletter u l-ebda pjan ta' tkabbir. Jekk jidher utli, tista' titlob biex tipprovah meta jinfetaħ ftit aktar."]},{"n":144,"texts":["AI-gile huwa bord kanban għal bniedem wieħed u ħafna aġenti tal-AI paċenzjużi. Jaħdem fuq il-kompjuter tiegħek stess u huwa għal kollox b'xejn. Inti żżid proġetti, u kull proġett jaqla' lead u tim żgħir. Tiddiskuti mal-lead, kemmxejn bħal fuq Discord, u tiddeskrivi idea; il-lead jagħmilha karti u pjan, u jistenna li tagħfas Go. It-tim jaħdem mal-karti skont il-prijorità, b'għodda sempliċi tal-linja tal-kmandi magħmula għall-mudelli tal-lingwa. Qabel ma xi ħaġa tirritorna għandek, tester tal-AI isegwi l-passi f'kopja tal-app u jwaħħal screenshot. Ix-xogħol lest jasal fuq il-munzell tiegħek, mal-fajls li nbidlu, id-diff u l-iscreenshots. Inti taċċettah, jew tħalli kumment u t-tim iqum u jerġa' jipprova. Kull ma jsir jidher fuq il-bord, f'kolonni mill-Backlog sa Lest. Ma jeħtieġ l-ebda kont. Int biss tista' tmexxi karta għal Lest.","Jum ma' AI-gile, bejn wieħed u ieħor. Filgħaxija tħalli ftit kummenti: din il-buttuna hi fil-post ħażin, dik il-lista għandha tinżamm ordnata, nistgħu nkollhom mod skur. Tmur torqod. L-aġenti jaqraw il-kummenti, jagħmlu l-bidliet, jittestjawhom u jirritornawhom lilek. Jekk Biex isir jispiċċa, l-għassa tal-lejl timlieh mill-backlog b'karti li ma jeħtieġu l-ebda tweġiba minnek. Filgħodu hemm munzell qasir wieħed: par ta' mistoqsijiet u ftit affarijiet biex tipprova, kull wieħed b'passi li persuna ngħasana tista' ssegwi u screenshot ta' kif jaħdem. Tikklikkja minnu, taċċetta t-tajba u tibgħat lura l-bqija. Għadd tat-tokens juri kemm intuża dan kollu, u l-Mod bla Tokens hemm għal ġimgħat irqaq. Jekk xi ħaġa ma tkunx ċara, it-tim jistaqsi qabel ma jmur 'il quddiem. Imbagħad tieħu l-kolazzjon, li l-aġenti għadhom ma jistgħux jgħinu fih.","L-ewwel, x'mhuwiex AI-gile. Mhuwiex startup, mhuwiex għall-bejgħ, u ħadd ma qed jiġbor id-dejta tiegħek. Huwa bord b'xejn li jaħdem fuq il-kompjuter tiegħek, mingħajr kontijiet, trackers jew cookies. X'inhu: post wieħed irranġat biex tara l-proġetti kollha tiegħek tal-kodiċi bl-AI f'daqqa, b'tim ta' aġenti jagħmlu l-karti u inti tieħu d-deċiżjonijiet. Jingħaqad karti relatati, isewwi titli mħawdin, u josserva kemm il-kodiċi jibqa' irqiq. Jitkellem madwar 120 lingwa, mill-Malti sal-pirata u l-Klingon. Il-ħbieb jistgħu jibagħtu messaġġi lil xulxin, privatament u ċifrati. Inbena minn Rich u numru kbir ta' aġenti paċenzjużi, li l-aktar użawh huma stess. Ma jbigħ xejn, ma jitlob xejn, u ma jgħaddi xejn lil ħadd. Qiegħed f'pre-alpha magħluqa, għalhekk f'xi postijiet għadu mhux rfinut. Jekk jidher divertenti, itlob b'ġentilezza u forsi tidħol kmieni."]}],"quips":{"1":"Kelma waħda. Kuraġġuża. Forsi kuraġġuża żżejjed.","3":"Tliet kelmiet. Diġà aktar onesti mill-biċċa l-kbira tal-paġni tal-prodotti.","8":"Tmien kelmiet. Għadu iqsar minn stand-up.","21":"It-tulijiet huma story points, mill-mod. Naturalment.","55":"Ħamsa u ħamsin kelma. Żewġ karti ntemmu waqt li qrajt dan.","144":"Din kienet it-tawwala. M'hemm l-ebda 233. L-aġenti marru jorqdu."}},"timeline":{"first-idea.name":"L-ewwel idea","first-idea.line":"L-ewwel konversazzjoni ta' kollox, qabel ma kien jeżisti kodiċi.","first-board.name":"L-ewwel bord","first-board.line":"Bord li jżomm rendikont tal-bini tiegħu stess: karti, kolonni, ġbid u ċaqliq, proġetti.","team-roles.name":"Tim u rwoli","team-roles.line":"Profili tal-aġenti, mudelli tat-timijiet, spazji u min jagħmel xiex.","install.name":"Installazzjoni u rilaxxi","install.line":"Zip li ħabib jista' jinstalla, aġġornamenti awtomatiċi, kanali u rollback.","usage-saver.name":"Tfaddil tal-użu","usage-saver.line":"Kejl ta' kemm jiswew it-tħaddim, kodiċi irqiq, u l-limitu tiegħek jitfaddal.","friends.name":"Ħbieb u qsim","friends.line":"DMs privati, relay imħawwad, stediniet, rwoli u proġetti maqsuma.","languages.name":"Lingwi","languages.line":"Kull test tal-iskrin f'fajl tal-lingwa, bl-Olandiż u l-Fjamming l-ewwel.","ai-tester.name":"Tester tal-AI","ai-tester.line":"Tester jiċċekkja kull konsenja l-ewwel u juri x'ra.","website.name":"Is-sit","website.line":"aigile.lol, it-teaser u din l-iskeda taż-żmien.","streaming.name":"Chat u streaming","streaming.line":"Discord, Twitch, OBS, mod tal-istreamer, GIFs u emojis.","no-ai.name":"Edizzjoni bla AI","no-ai.line":"Bord għal nies li jikkodifikaw mingħajr AI, u bordijiet pubbliċi.","night-watch.name":"Għassa tal-lejl","night-watch.line":"Għassies u Scrum Master iżommu t-timijiet fuq il-binarju waqt li torqod.","p-more.name":"Kull ħaġa oħra","p-more.line":"Ideat iżgħar li għadhom jistennew id-dawra tagħhom.","p-android.name":"Telefon u Android","p-android.line":"Dħul fil-bord tiegħek mit-telefon, imbagħad app nattiva għall-Android.","p-release.name":"Alpha u aktar 'il quddiem","p-release.line":"Alpha magħluqa, is-sit live, imbagħad il-beta.","p-languages.name":"Aktar lingwi","p-languages.line":"Aktar minn mitt lingwa, u mod ta' immersjoni għal min qed jitgħallem.","p-engines.name":"Aktar magni tal-AI","p-engines.line":"Agħżel Claude, Codex jew Gemini għal kull aġent.","p-pro.name":"Prattika professjonali","p-pro.line":"Tikketti tar-riskju, bibien tal-merge, karti tal-inċidenti u ħitan tal-ħarsien.","p-self.name":"Ngħożżuk","p-self.line":"Mod għajjien, tfakkiriet ta' kura personali u 4:20.","p-servers.name":"Servers u skala","p-servers.line":"Settings globali tas-server, rwoli u ppjanar għat-tkabbir.","p-livestream.name":"Żidiet għall-istreaming","p-livestream.line":"Chat ta' Twitch, emojis personalizzati u veduta live pubblika."},"words":{"button":"📖 Kliem tal-iżviluppaturi","h":"📖 Kliem tal-iżviluppaturi spjegat","intro":"Il-kliem li jużaw l-iżviluppaturi (u t-timijiet tal-AI), bil-Malti sempliċi.","search":"Fittex kelma…","none":"Ebda kelma ma taqbel ma' dak.","close":"Agħlaq","list":[{"id":"backlog","word":"Backlog","text":"Ideat u xogħol li għadu mhux ippjanat. Xejn hemmhekk ma jitħadem sakemm ma jmurx għal Biex isir."},{"id":"sprint","word":"Sprint","text":"Perjodu qasir ta' xogħol (spiss ġimgħa jew tnejn) b'sett ta' karti miftiehem biex jitlestew.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"Check-in rapidu: x'għamel kull membru tat-tim, x'se jagħmel wara, u x'qed iwaqqfu.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Xi ħaġa li ma taħdimx kif suppost.","also":["bugs"]},{"id":"test","word":"Test","text":"Tipprova biċċa xogħol lesta biex tara li tagħmel dak li ntalab, qabel ma taċċettaha.","also":["testijiet","tittestja","jiġu ttestjati"],"noTip":1},{"id":"commit","word":"Commit","text":"Snapshot issejvjat tal-kodiċi, b'nota qasira ta' x'inbidel. Dejjem tista' terġa' lura għal wieħed.","also":["commits"]},{"id":"push","word":"Push","text":"Tibgħat snapshots issejvjati (commits) minn dan il-kompjuter fuq GitHub, biex ikunu ssejvjati u kondiviżi."},{"id":"branch","word":"Branch","text":"Linja separata ta' xogħol fil-kodiċi, biex isiru bidliet mingħajr ma tmiss il-verżjoni prinċipali.","also":["branches"]},{"id":"merge","word":"Merge","text":"Ngħaqqdu l-bidliet ta' branch lura mal-verżjoni prinċipali."},{"id":"repo","word":"Repo","text":"Il-folder tal-kodiċi tal-proġett u l-istorja sħiħa tiegħu ta' commits, ġeneralment miżmum ukoll fuq GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"Tirranġa l-kodiċi mingħajr ma tibdel dak li jagħmel: fajls iżgħar, ismijiet iktar ċari, inqas ripetizzjoni."},{"id":"deploy","word":"Deploy","text":"Tqiegħed verżjoni ġdida live, pereżempju fuq server fejn in-nies jużawha."},{"id":"kanban","word":"Kanban","text":"Bord b'kolonni (Biex isir, Għaddej, Lest) fejn il-karti jimxu mix-xellug lejn il-lemin hekk kif isir ix-xogħol."},{"id":"wip","word":"WIP limit","text":"Work in progress: l-aktar karti li kolonna għandha żżomm, biex it-tim itemm l-affarijiet qabel jibda aktar.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Titlob li l-bidliet ta' branch jiġu ċċekkjati u mgħaqqda mal-verżjoni prinċipali.","also":["PR"]},{"id":"hook","word":"Hook","text":"Kmand żgħir li jaħdem waħdu f'mument stabbilit, eż. meta tibda sessjoni tal-AI, biex it-tim jisma' l-kummenti tiegħek.","also":["hooks"]},{"id":"token","word":"Token","text":"L-unità li biha jingħadd l-użu tal-AI: bejn wieħed u ieħor ftit ittri ta' test moqrija jew miktuba. Inqas tokens, aktar jibqa' mill-pjan tiegħek.","also":["tokens"]},{"id":"agent","word":"Aġent","text":"AI li taħdem waħedha fuq kompitu: taqra l-kodiċi, tagħmel bidliet, tmexxi kontrolli, u tirrapporta lura.","also":["aġenti","agent","agents"]}]}};
